import numpy as np
import trimesh
from scipy.spatial import ConvexHull

try:
    import open3d as o3d
    O3D_AVAILABLE = True
except Exception:
    O3D_AVAILABLE = False

class MeshReconstructor:
    """Reconstruct 3D meshes from point clouds and depth maps."""

    @staticmethod
    def pointcloud_to_mesh(points: np.ndarray, method: str = "poisson") -> trimesh.Trimesh:
        """Convert a point cloud to a mesh.

        Supports `(N, 3)` points or `(N, 6)` where the last 3 columns are normals.
        """
        if points.ndim != 2 or points.shape[1] < 3:
            raise ValueError("points must have shape (N, 3) or (N, 6)")

        normals = None
        if points.shape[1] >= 6:
            normals = points[:, 3:6]
            points = points[:, :3]

        normalized_method = method.lower().strip()
        if normalized_method == "convex":
            return MeshReconstructor.convex_hull_mesh(points)
        if normalized_method == "poisson":
            if O3D_AVAILABLE:
                return MeshReconstructor._poisson_reconstruction_o3d(points, normals=normals, depth=9)
            return MeshReconstructor.poisson_reconstruction(points)
        if normalized_method in {"ball", "ball_pivot", "ball-pivot"}:
            if O3D_AVAILABLE:
                return MeshReconstructor._ball_pivot_mesh_o3d(points, normals=normals, radius=None)
            return MeshReconstructor.ball_pivot_mesh(points)
        raise ValueError(f"Unsupported reconstruction method: {method}")

    @staticmethod
    def convex_hull_mesh(points: np.ndarray) -> trimesh.Trimesh:
        """Create a watertight-ish mesh using a convex hull."""
        try:
            hull = ConvexHull(points)
            return trimesh.Trimesh(vertices=hull.points, faces=hull.simplices)
        except Exception as exc:
            print(f"Convex hull failed: {exc}, using point cloud directly")
            return trimesh.Trimesh(vertices=points)

    @staticmethod
    def ball_pivot_mesh(points: np.ndarray, radius: float = 0.1) -> trimesh.Trimesh:
        """Fallback ball-pivot implementation via voxelization."""
        try:
            mesh = trimesh.Trimesh(vertices=points)
            mesh_voxel = mesh.voxelized(pitch=max(1e-4, radius * 0.1))
            return mesh_voxel.as_mesh()
        except Exception as exc:
            print(f"Ball pivot failed: {exc}")
            return MeshReconstructor.convex_hull_mesh(points)

    @staticmethod
    def poisson_reconstruction(points: np.ndarray, depth: int = 10) -> trimesh.Trimesh:
        """Fallback reconstruction using Delaunay hull surfaces."""
        try:
            from scipy.spatial import Delaunay

            if len(points) > 5000:
                indices = np.random.choice(len(points), 5000, replace=False)
                points_sample = points[indices]
            else:
                points_sample = points

            delaunay = Delaunay(points_sample)
            mesh = trimesh.Trimesh(vertices=delaunay.points, faces=delaunay.convex_hull)
            if len(mesh.vertices) > 0 and len(mesh.faces) > 0:
                return mesh
            return MeshReconstructor.convex_hull_mesh(points)
        except Exception as exc:
            print(f"Delaunay triangulation failed: {exc}, using convex hull")
            return MeshReconstructor.convex_hull_mesh(points)

    @staticmethod
    def _poisson_reconstruction_o3d(points: np.ndarray, normals: np.ndarray | None = None, depth: int = 9) -> trimesh.Trimesh:
        """Open3D Poisson reconstruction with robust fallbacks."""
        try:
            pcd = o3d.geometry.PointCloud()
            pcd.points = o3d.utility.Vector3dVector(points.astype(np.float64))

            if normals is not None and normals.shape == points.shape:
                nrm = normals.astype(np.float64)
                nrm = nrm / (np.linalg.norm(nrm, axis=1, keepdims=True) + 1e-12)
                pcd.normals = o3d.utility.Vector3dVector(nrm)
            else:
                pcd.estimate_normals(search_param=o3d.geometry.KDTreeSearchParamHybrid(radius=0.05, max_nn=30))
                pcd.orient_normals_consistent_tangent_plane(20)

            mesh_o3d, densities = o3d.geometry.TriangleMesh.create_from_point_cloud_poisson(pcd, depth=depth)
            mesh_o3d = mesh_o3d.crop(pcd.get_axis_aligned_bounding_box())

            density_values = np.asarray(densities)
            if density_values.size == len(mesh_o3d.vertices):
                threshold = np.quantile(density_values, 0.1)
                mesh_o3d.remove_vertices_by_mask(~(density_values > threshold))

            mesh_o3d.remove_duplicated_vertices()
            mesh_o3d.remove_degenerate_triangles()
            mesh_o3d.remove_non_manifold_edges()
            mesh_o3d.compute_vertex_normals()

            vertices = np.asarray(mesh_o3d.vertices, dtype=np.float64)
            faces = np.asarray(mesh_o3d.triangles, dtype=np.int64)
            return trimesh.Trimesh(vertices=vertices, faces=faces, process=False)
        except Exception as exc:
            print(f"Open3D Poisson failed: {exc}, falling back to Delaunay")
            return MeshReconstructor.poisson_reconstruction(points)

    @staticmethod
    def _ball_pivot_mesh_o3d(points: np.ndarray, normals: np.ndarray | None = None, radius: float | None = None) -> trimesh.Trimesh:
        """Open3D ball-pivot reconstruction with adaptive radius."""
        try:
            pcd = o3d.geometry.PointCloud()
            pcd.points = o3d.utility.Vector3dVector(points.astype(np.float64))

            if normals is not None and normals.shape == points.shape:
                nrm = normals.astype(np.float64)
                nrm = nrm / (np.linalg.norm(nrm, axis=1, keepdims=True) + 1e-12)
                pcd.normals = o3d.utility.Vector3dVector(nrm)
            else:
                pcd.estimate_normals(search_param=o3d.geometry.KDTreeSearchParamHybrid(radius=0.03, max_nn=30))
                pcd.orient_normals_consistent_tangent_plane(20)

            if radius is None:
                dists = pcd.compute_nearest_neighbor_distance()
                radius = max(1e-4, float(np.mean(dists)) * 1.5) if len(dists) > 0 else 0.01

            radii = o3d.utility.DoubleVector([radius, radius * 2.0])
            mesh_o3d = o3d.geometry.TriangleMesh.create_from_point_cloud_ball_pivoting(pcd, radii)

            mesh_o3d.remove_duplicated_vertices()
            mesh_o3d.remove_degenerate_triangles()
            mesh_o3d.remove_non_manifold_edges()
            mesh_o3d.compute_vertex_normals()

            vertices = np.asarray(mesh_o3d.vertices, dtype=np.float64)
            faces = np.asarray(mesh_o3d.triangles, dtype=np.int64)
            return trimesh.Trimesh(vertices=vertices, faces=faces, process=False)
        except Exception as exc:
            print(f"Open3D Ball Pivoting failed: {exc}, falling back to convex hull")
            return MeshReconstructor.convex_hull_mesh(points)

    @staticmethod
    def voxel_to_mesh(voxel_grid: np.ndarray) -> trimesh.Trimesh:
        """Convert a binary voxel grid into a mesh."""
        voxel_grid = voxel_grid.astype(bool)
        return trimesh.voxel.Voxel(voxel_grid).as_mesh()

    @staticmethod
    def smooth_mesh(mesh: trimesh.Trimesh, iterations: int = 5) -> trimesh.Trimesh:
        """Apply Laplacian smoothing to a mesh in-place."""
        try:
            trimesh.smoothing.filter_laplacian(mesh, iterations=iterations, implicit_time_steps=1)
            return mesh
        except Exception:
            return mesh

    @staticmethod
    def mesh_from_depth_map(depth_map: np.ndarray, fx: float = 500, fy: float = 500) -> trimesh.Trimesh:
        """Create mesh from a depth map using pinhole camera assumptions."""
        h, w = depth_map.shape
        x = np.arange(w)
        y = np.arange(h)
        xx, yy = np.meshgrid(x, y)

        xx = (xx - w / 2) / fx
        yy = (yy - h / 2) / fy

        points = np.stack([xx * depth_map, yy * depth_map, depth_map], axis=-1).reshape(-1, 3)
        points = points[depth_map.flatten() > 0]
        return MeshReconstructor.pointcloud_to_mesh(points)

"""Analyze and optimize meshes for 3D printability"""

import numpy as np
from trimesh import Trimesh

class PrintabilityAnalyzer:
    """Check for print-readiness issues"""

    # Minimum feature sizes (mm)
    MIN_FEATURE_SIZES = {
        "fdm_pla": 0.4,      # FDM nozzle size
        "fdm_petg": 0.5,     # PETG slightly thicker
        "resin_standard": 0.2,
        "resin_high_detail": 0.1,
    }

    # Minimum wall thickness (mm)
    MIN_WALL_THICKNESS = {
        "fdm": 1.5,
        "resin": 0.8,
        "metal": 2.0,
    }

    # Maximum overhang angle (degrees from vertical)
    MAX_OVERHANG_ANGLE = 45  # degrees

    @staticmethod
    def analyze(mesh: Trimesh, material: str = "fdm") -> dict:
        """
        Analyze mesh for printability issues

        Args:
            mesh: Trimesh to analyze
            material: "fdm", "resin", or "metal"

        Returns:
            Printability report with score and issues
        """
        report = {
            "material": material,
            "score": 100,  # Out of 100
            "issues": [],
            "warnings": [],
            "print_difficulty": "EASY",
            "support_needed": False,
            "estimated_print_time_minutes": 0,
            "estimated_weight_grams": 0,
        }

        # Check 1: Mesh validity
        try:
            if len(mesh.vertices) == 0 or len(mesh.faces) == 0:
                report["issues"].append("Mesh has no geometry - may fail to print")
                report["score"] -= 20
        except:
            pass

        # Check 2: Closed mesh
        if not mesh.is_watertight:
            report["issues"].append("Mesh is not watertight - needs sealing before printing")
            report["score"] -= 30

        # Check 3: Thin walls
        wall_thickness = PrintabilityAnalyzer._estimate_wall_thickness(mesh)
        min_wall = PrintabilityAnalyzer.MIN_WALL_THICKNESS.get(material, 1.5)

        if wall_thickness > 0 and wall_thickness < min_wall:
            report["warnings"].append(
                f"Thin walls detected ({wall_thickness:.2f}mm < {min_wall}mm minimum) - increase model scale or add internal structure"
            )
            report["score"] -= 10

        # Check 4: Overhangs
        overhangs = PrintabilityAnalyzer._detect_overhangs(mesh)
        if overhangs["has_overhangs"]:
            report["support_needed"] = True
            report["warnings"].append(
                f"Overhanging features detected - supports will be auto-generated"
            )
            if overhangs["severe_overhangs"]:
                report["issues"].append("Severe overhangs may require manual adjustment")
                report["score"] -= 15
            else:
                report["score"] -= 5

        # Check 5: Size reasonableness
        bounds = mesh.bounds
        max_dim = max(
            bounds[1][0] - bounds[0][0],
            bounds[1][1] - bounds[0][1],
            bounds[1][2] - bounds[0][2]
        )

        if max_dim < 5:
            report["warnings"].append(f"Model very small ({max_dim:.1f}mm) - may be hard to handle post-print")
            report["score"] -= 5
        elif max_dim > 80:
            report["warnings"].append(f"Model very large ({max_dim:.1f}mm) - consider splitting into parts")
            report["score"] -= 10

        # Check 6: Volume/printability
        if mesh.volume > 0:
            # Estimate material weight (varies by material)
            density_g_cm3 = {
                "fdm": 1.24,  # PLA
                "resin": 1.20,
                "metal": 8.0,
            }
            density = density_g_cm3.get(material, 1.2)
            volume_cm3 = mesh.volume / 1000  # Convert mm³ to cm³
            report["estimated_weight_grams"] = volume_cm3 * density

        # Estimate print time (rough)
        try:
            if material == "fdm":
                # Rough: ~10mm² per minute at 0.2mm layer
                estimated_area = bounds[1][0] * bounds[1][1] / 100  # Rough layer area
                if np.isfinite(estimated_area):
                    report["estimated_print_time_minutes"] = int(max(1, estimated_area * 10))
                else:
                    report["estimated_print_time_minutes"] = 30
            elif material == "resin":
                # Much faster: ~30 seconds per layer
                height = bounds[1][2] - bounds[0][2]
                if np.isfinite(height):
                    layers = int(max(10, height / 0.05))  # 50 micron layers
                    report["estimated_print_time_minutes"] = int(max(1, layers * 0.5 / 60))
                else:
                    report["estimated_print_time_minutes"] = 10
        except:
            report["estimated_print_time_minutes"] = 30

        # Set difficulty
        if report["score"] >= 90:
            report["print_difficulty"] = "VERY EASY"
        elif report["score"] >= 75:
            report["print_difficulty"] = "EASY"
        elif report["score"] >= 60:
            report["print_difficulty"] = "MODERATE"
        elif report["score"] >= 40:
            report["print_difficulty"] = "DIFFICULT"
        else:
            report["print_difficulty"] = "VERY DIFFICULT"

        return report

    @staticmethod
    def _estimate_wall_thickness(mesh: Trimesh) -> float:
        """Estimate minimum wall thickness"""
        # Simplified: use mesh thickness estimation
        try:
            thickness = mesh.section_thickness()
            return float(thickness) if thickness else 0
        except:
            return 0

    @staticmethod
    def _detect_overhangs(mesh: Trimesh, max_angle: float = 45) -> dict:
        """Detect overhanging features"""
        result = {
            "has_overhangs": False,
            "severe_overhangs": False,
            "overhang_count": 0,
            "degrees_from_vertical": max_angle,
        }

        try:
            # Check face normals against Z-axis
            normals = mesh.face_normals
            vertical = np.array([0, 0, 1])

            # Calculate angles
            angles = np.arccos(np.clip(np.dot(normals, vertical), -1, 1))
            angles_deg = np.degrees(angles)

            # Check for overhangs (>45 degrees from vertical = <45 degrees from horizontal)
            overhang_faces = np.where(angles_deg > (90 - max_angle))[0]

            if len(overhang_faces) > 0:
                result["has_overhangs"] = True
                result["overhang_count"] = len(overhang_faces)

                # Severe if very steep
                severe = np.where(angles_deg > 85)[0]  # Nearly horizontal
                if len(severe) > len(overhang_faces) * 0.1:
                    result["severe_overhangs"] = True
        except:
            pass

        return result

    @staticmethod
    def get_printability_score(mesh: Trimesh, material: str = "fdm") -> tuple[int, str]:
        """Get quick printability score (0-100) and status string"""
        report = PrintabilityAnalyzer.analyze(mesh, material)
        score = max(0, min(100, report["score"]))

        if score >= 90:
            status = "[EXCELLENT] Print with confidence"
        elif score >= 75:
            status = "[GOOD] Should print fine"
        elif score >= 60:
            status = "[OK] Acceptable - may need supports"
        elif score >= 40:
            status = "[CAUTION] Risky - review carefully before printing"
        else:
            status = "[DIFFICULT] Significant adjustments needed"

        return score, status

import trimesh
import numpy as np
from pathlib import Path
from typing import Tuple, Optional
import torch

class STLProcessor:
    """Process STL files for training and analysis"""

    @staticmethod
    def load_stl(filepath: str) -> trimesh.Trimesh:
        """Load STL file"""
        try:
            mesh = trimesh.load(filepath)
            return mesh
        except Exception as e:
            raise Exception(f"Error loading STL: {e}")

    @staticmethod
    def get_mesh_info(mesh: trimesh.Trimesh) -> dict:
        """Extract features from mesh for training"""
        return {
            "vertices_count": len(mesh.vertices),
            "faces_count": len(mesh.faces),
            "surface_area": float(mesh.area),
            "volume": float(mesh.volume),
            "bounds": mesh.bounds.tolist(),
            "center_mass": mesh.center_mass.tolist(),
        }

    @staticmethod
    def normalize_mesh(mesh: trimesh.Trimesh, target_size: float = 1.0) -> trimesh.Trimesh:
        """Normalize mesh to unit size and center"""
        mesh.apply_translation(-mesh.center_mass)
        mesh.apply_scale(target_size / mesh.extents.max())
        return mesh

    @staticmethod
    def mesh_to_pointcloud(mesh: trimesh.Trimesh, sample_count: int = 10000) -> np.ndarray:
        """Convert mesh to point cloud"""
        points, _ = trimesh.sample.sample_surface(mesh, sample_count)
        return points

    @staticmethod
    def pointcloud_to_tensor(points: np.ndarray) -> torch.Tensor:
        """Convert point cloud to PyTorch tensor"""
        return torch.from_numpy(points).float()

    @staticmethod
    def save_stl(mesh: trimesh.Trimesh, filepath: str):
        """Save mesh to STL file"""
        mesh.export(filepath, file_type='stl')

    @staticmethod
    def simplify_mesh(mesh: trimesh.Trimesh, target_reduction: float = 0.5) -> trimesh.Trimesh:
        """Simplify mesh using quadric mesh simplification"""
        try:
            simplified = mesh.simplify_quadric_mesh_simplification(
                target_reduction=target_reduction
            )
            return simplified
        except:
            return mesh

