        y = np.arange(h)
        xx, yy = np.meshgrid(x, y)

        xx = (xx - w / 2) / fx
        yy = (yy - h / 2) / fy

        points = np.stack([xx * depth_map, yy * depth_map, depth_map], axis=-1).reshape(-1, 3)
        points = points[depth_map.flatten() > 0]
        return MeshReconstructor.pointcloud_to_mesh(points)

